/* Satu rekening operasional. Saldo sengaja dibuat TIDAK cukup untuk membayar
   semua yang lolos kontrol, supaya cabang "kas tidak cukup" benar-benar hidup
   di setiap demo, bukan cuma ada di kode. */
const d = new Date();
return [{ json: {
  account_code: 'OPS-IDR-01', bank_name: 'Bank Mandiri', account_number: '1220004455667',
  currency: 'IDR', balance: 900000000, min_buffer: 150000000, cost_of_cash_pct: 12,
  as_of: d.toISOString().slice(0, 10)
} }];

/* Satu pembayaran lama yang sudah beres. Ada supaya penjaga pembayaran-ganda
   punya sesuatu yang nyata untuk ditangkap: faktur yang sama diajukan lagi
   di run hari ini. Tanpa baris ini, penjaga itu tidak pernah terbukti. */
function hari(n) { const d = new Date(); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); }
return [{ json: {
  line_key: 'RUN-SEED|SINAR BAJA ELEKTRIK|PAY-1007',
  run_key: 'RUN-SEED', vendor: 'Sinar Baja Elektrik', invoice_number: 'PAY-1007',
  amount: 22000000, currency: 'IDR', status: 'settled', route_to: 'accounting_auto',
  hold_code: '', hold_reason: '', account_number_masked: '******7766',
  pay_on: hari(-21), discount_taken: 0, bank_ref: 'TRX-SEED-0001',
  settled_on: hari(-20), reject_reason: '', execution_id: 'seed'
} }];

/* Faktur yang sudah lolos pencocokan tiga arah dan menunggu dibayar.
   Ditulis ke AP Invoice Ledger — tabel yang sama yang ditulis workflow
   pencocokan tiga arah — supaya kedua workflow portofolio benar-benar
   bersambung: faktur disetujui di sana, uangnya keluar di sini.
   po_number 'PAY-RUN' dipakai sebagai penanda supaya reset ini hanya
   menghapus barisnya sendiri dan tidak mengganggu demo AP. */
function hari(n) { const d = new Date(); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); }
const f = [
  ['Sinar Baja Elektrik',     'PAY-1001',   8760000, 'auto_approve',   'accounting_auto', -4,  'Cocok penuh, di bawah plafon tanpa sentuhan.'],
  ['Mitra Logistik Nusantara','PAY-1002',  50400000, 'needs_approval', 'manager',         -6,  'Di atas plafon tanpa sentuhan.'],
  ['Cahaya Teknik Presisi',   'PAY-1003', 120000000, 'needs_approval', 'manager',         -5,  'Cocok penuh. Rekening vendornya yang bermasalah, bukan fakturnya.'],
  ['PT Kemasan Prima',        'PAY-1004',  47000000, 'needs_approval', 'manager',         -9,  'Cocok penuh, tapi vendornya sedang ditahan.'],
  ['Berkah Jaya Mandiri',     'PAY-1005',   6000000, 'auto_approve',   'accounting_auto', -2,  'Kecil dan bersih.'],
  ['Anugerah Metalindo',      'PAY-1006', 480000000, 'needs_approval', 'director',        -11, 'Nilai besar; menembus ambang tanda tangan ganda.'],
  ['Sinar Baja Elektrik',     'PAY-1007',  22000000, 'auto_approve',   'accounting_auto', -24, 'Faktur ini SUDAH dibayar di run sebelumnya. Diajukan lagi untuk menguji penjaga pembayaran ganda.'],
  ['Berkah Jaya Mandiri',     'PAY-1008', 310000000, 'needs_approval', 'director',        -7,  'Sah, tapi kas hari ini tidak akan sampai ke sini.'],
  ['Mitra Logistik Nusantara','PAY-1009',   3500000, 'auto_approve',   'accounting_auto', -1,  'Kecil dan bersih.'],
];
return f.map(function (r) {
  return { json: {
    invoice_key: r[0].toUpperCase() + '|' + r[1],
    vendor: r[0], invoice_number: r[1], po_number: 'PAY-RUN',
    amount: r[2], currency: 'IDR', decision: r[3], route_to: r[4],
    exception_code: '', note: r[6], processed_at: hari(r[5]) + 'T08:00:00.000Z',
    execution_id: 'seed', qty_billed: 0
  } };
});
